sysauto_script.script:
// RESTPulse — Scheduled Evaluation
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function () {
    try {
        var engine = new RESTPulseEngine();
        var summary = engine.runEvaluation();
        gs.info('RESTPulse: evaluation complete. evaluated=' + summary.evaluated +
            ' healthy=' + summary.healthy +
            ' degraded=' + summary.degraded +
            ' critical=' + summary.critical);

        var alerter = new RESTPulseAlert();
        var alertResult = alerter.runAlertCycle();
        gs.info('RESTPulse: alert cycle complete. checked=' + alertResult.checked +
            ' alerted=' + alertResult.alerted +
            ' suppressed_quiet=' + alertResult.suppressed_quiet +
            ' suppressed_dedup=' + alertResult.suppressed_dedup);
    } catch (e) {
        gs.error('RESTPulse: scheduled evaluation failed. ' + e);
    }
})();
